// Reference loader and self-consistency checks for the model entitlement refusal golden (WS10-S1):
//
//   apps/Model Plane/api/contracts/model-entitlement-refusals.json
//
// The golden is generated by mp-contracts (model_entitlement::catalogue_json), never written by
// hand, and the SPA renders each code in Norwegian and English from it. A digest pin proves the
// file did not change; it says nothing about whether the file is well formed. This module checks
// that: no unknown field, no missing field, only the two codes and five reasons the contract has,
// no sentence with a placeholder the wire does not fill, a body that carries a model id and a
// reason and nothing else (the golden is content-free by construction), and agreement with the
// entitlement matrix (apps/Model Plane/api/contracts/model-entitlement-matrix.json) on the
// reason vocabulary and on the refusal rows.
//
// Nothing here evaluates a matrix row: mp-contracts and org-core do that with their own real
// functions. These are necessary conditions, not a second resolver.
//
// Used by scripts/tests/model-entitlement-contract-sync.test.sh (repo-level drift check) and by
// scripts/tests/model-entitlement-contract-schema.test.mjs.
//
//   node scripts/tests/model-entitlement-contract-schema.mjs [repoRoot]
//
// Exit status is non-zero on any finding. A missing golden is a finding, never a skip.

import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const REFUSALS_PATH = 'apps/Model Plane/api/contracts/model-entitlement-refusals.json';
export const MATRIX_PATH = 'apps/Model Plane/api/contracts/model-entitlement-matrix.json';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

export const CODES = ['model_not_entitled', 'model_entitlement_unavailable'];
export const REASONS = [
  'not_in_allow_list',
  'explicitly_denied',
  'no_entitled_route',
  'member_not_found',
  'deployment_allowlist',
];
const ACTIONS = ['retry', 'choose_another_model'];
const HTTP_STATUSES = [403, 503];
const GRPC_CODES = ['permission_denied', 'unavailable'];

const TOP_KEYS = ['codes', 'contract', 'generated_by', 'reasons', 'version', 'wire'];
const CODE_KEYS = ['action', 'code', 'grpc_code', 'http_status', 'message_en', 'retryable', 'takes_reason'];
const REASON_KEYS = ['message_en', 'names_model', 'reason'];
const WIRE_KEYS = [
  'details',
  'details_when',
  'grpc_kind_trailer',
  'grpc_reason_trailer',
  'json_body',
  'max_model_id_bytes',
  'sse_event',
  'sse_fields',
];
/** What a refusal body may carry. Anything else (a prompt, a message, a policy) is content. */
const BODY_KEYS = ['action', 'code', 'details', 'message', 'retryable'];
const DETAILS_KEYS = ['model', 'reason'];

const sameSet = (a, b) => a.length === b.length && [...a].sort().every((value, n) => value === [...b].sort()[n]);
const keysOf = (value) => (value && typeof value === 'object' && !Array.isArray(value) ? Object.keys(value) : null);

function exactKeys(value, expected, where, out) {
  const keys = keysOf(value);
  if (!keys) {
    out.push(`${where}: must be an object`);
    return false;
  }
  for (const key of keys) if (!expected.includes(key)) out.push(`${where}: unknown field '${key}'`);
  for (const key of expected) if (!keys.includes(key)) out.push(`${where}: missing field '${key}'`);
  return true;
}

/** Placeholders a sentence holds: `{name}` tokens. */
const placeholders = (text) => [...text.matchAll(/\{([a-z_]+)\}/g)].map((match) => match[1]);

export function validateRefusals(doc) {
  const out = [];
  if (!exactKeys(doc, TOP_KEYS, 'refusals', out)) return out;
  if (doc.contract !== 'model-plane.model-entitlement-refusals') out.push(`refusals: contract is '${doc.contract}'`);
  if (doc.version !== 1) out.push(`refusals: version is ${doc.version}, this loader reads 1`);

  if (exactKeys(doc.wire, WIRE_KEYS, 'refusals.wire', out)) {
    const body = doc.wire.json_body;
    if (!sameSet(body?.error ?? [], BODY_KEYS) || keysOf(body)?.length !== 1) {
      out.push(`refusals.wire.json_body: must be {"error": ${JSON.stringify(BODY_KEYS)}}: a refusal body carries no content`);
    }
    if (!sameSet(doc.wire.details ?? [], DETAILS_KEYS)) {
      out.push(`refusals.wire.details: must be exactly ${JSON.stringify(DETAILS_KEYS)}: a model id and a reason`);
    }
    if (doc.wire.details_when !== 'takes_reason') out.push('refusals.wire.details_when: must be takes_reason');
    if (doc.wire.sse_event !== 'error') out.push('refusals.wire.sse_event: must be error');
    if (!Number.isInteger(doc.wire.max_model_id_bytes) || doc.wire.max_model_id_bytes < 1) {
      out.push('refusals.wire.max_model_id_bytes: must be a positive integer');
    }
  }

  if (!Array.isArray(doc.codes)) {
    out.push('refusals.codes: must be an array');
  } else {
    const seen = [];
    for (const [n, entry] of doc.codes.entries()) {
      const where = `refusals.codes[${n}]`;
      if (!exactKeys(entry, CODE_KEYS, where, out)) continue;
      if (!CODES.includes(entry.code)) out.push(`${where}: code '${entry.code}' is not one of ${CODES.join(', ')}`);
      if (seen.includes(entry.code)) out.push(`${where}: code '${entry.code}' is listed twice`);
      seen.push(entry.code);
      if (!ACTIONS.includes(entry.action)) out.push(`${where}: action '${entry.action}' is not one of ${ACTIONS.join(', ')}`);
      if (!HTTP_STATUSES.includes(entry.http_status)) out.push(`${where}: http_status ${entry.http_status} is not one of ${HTTP_STATUSES.join(', ')}`);
      if (!GRPC_CODES.includes(entry.grpc_code)) out.push(`${where}: grpc_code '${entry.grpc_code}' is not one of ${GRPC_CODES.join(', ')}`);
      if (typeof entry.retryable !== 'boolean') out.push(`${where}: retryable must be a boolean`);
      if (entry.retryable !== (entry.action === 'retry')) out.push(`${where}: retryable and action 'retry' must agree`);
      if (typeof entry.takes_reason !== 'boolean') out.push(`${where}: takes_reason must be a boolean`);
      if (typeof entry.message_en !== 'string' || entry.message_en.trim() === '') out.push(`${where}: message_en is empty`);
      else if (placeholders(entry.message_en).length > 0) out.push(`${where}: message_en holds a placeholder, and a code's own sentence names nothing`);
      // Fail closed: the unavailable code must never read as a verdict on a model.
      if (entry.code === 'model_entitlement_unavailable' && (entry.takes_reason || !entry.retryable || entry.http_status !== 503)) {
        out.push(`${where}: model_entitlement_unavailable must be retryable, 503 and carry no reason`);
      }
      if (entry.code === 'model_not_entitled' && (!entry.takes_reason || entry.retryable || entry.http_status !== 403)) {
        out.push(`${where}: model_not_entitled must carry a reason, be 403 and not be retryable`);
      }
    }
    for (const code of CODES) if (!seen.includes(code)) out.push(`refusals.codes: missing code '${code}'`);
  }

  if (!Array.isArray(doc.reasons)) {
    out.push('refusals.reasons: must be an array');
  } else {
    const seen = [];
    for (const [n, entry] of doc.reasons.entries()) {
      const where = `refusals.reasons[${n}]`;
      if (!exactKeys(entry, REASON_KEYS, where, out)) continue;
      if (!REASONS.includes(entry.reason)) out.push(`${where}: reason '${entry.reason}' is not in the vocabulary`);
      if (seen.includes(entry.reason)) out.push(`${where}: reason '${entry.reason}' is listed twice`);
      seen.push(entry.reason);
      if (typeof entry.message_en !== 'string' || entry.message_en.trim() === '') {
        out.push(`${where}: message_en is empty`);
        continue;
      }
      const holes = placeholders(entry.message_en);
      if (holes.some((name) => name !== 'model')) out.push(`${where}: message_en holds a placeholder the wire does not fill`);
      if (entry.names_model !== holes.includes('model')) out.push(`${where}: names_model must say whether message_en holds {model}`);
    }
    for (const reason of REASONS) if (!seen.includes(reason)) out.push(`refusals.reasons: missing reason '${reason}'`);
  }
  return out;
}

/** The refusal golden against the entitlement matrix it is the wire of. */
export function validateAgainstMatrix(refusals, matrix) {
  const out = [];
  const reasons = (refusals.reasons ?? []).map((entry) => entry.reason);
  if (!sameSet(matrix.vocabulary?.reasons ?? [], reasons)) {
    out.push(`matrix vocabulary.reasons ${JSON.stringify(matrix.vocabulary?.reasons)} differs from the refusal reasons ${JSON.stringify(reasons)}`);
  }
  const byCode = new Map((refusals.codes ?? []).map((entry) => [entry.code, entry]));
  const rows = matrix.rows ?? [];
  const required = matrix.vocabulary?.required_rows ?? [];
  if (!required.includes('r_refusal_is_content_free')) out.push("matrix: required_rows no longer names 'r_refusal_is_content_free'");
  if (!rows.some((row) => row.id === 'r_refusal_is_content_free')) out.push("matrix: row 'r_refusal_is_content_free' is missing");
  for (const row of rows) {
    if (row.kind === 'refusal') {
      const entry = byCode.get(row.expect?.code);
      if (!entry) {
        out.push(`matrix row ${row.id}: expects code '${row.expect?.code}', which the refusal catalogue does not have`);
        continue;
      }
      if (entry.http_status !== row.expect.http_status) out.push(`matrix row ${row.id}: http_status ${row.expect.http_status} differs from the catalogue's ${entry.http_status}`);
      if (!sameSet(row.expect.body_keys ?? [], BODY_KEYS)) out.push(`matrix row ${row.id}: body_keys must be exactly ${JSON.stringify(BODY_KEYS)}`);
      if (!sameSet(row.expect.details_keys ?? [], DETAILS_KEYS)) out.push(`matrix row ${row.id}: details_keys must be exactly ${JSON.stringify(DETAILS_KEYS)}`);
      if (!reasons.includes(row.input?.reason)) out.push(`matrix row ${row.id}: reason '${row.input?.reason}' is not in the refusal reasons`);
    }
    if (row.kind === 'availability' && row.expect?.decision === 'refuse') {
      const entry = byCode.get(row.expect.code);
      if (!entry) {
        out.push(`matrix row ${row.id}: expects code '${row.expect.code}', which the refusal catalogue does not have`);
        continue;
      }
      if (entry.http_status !== row.expect.http_status) out.push(`matrix row ${row.id}: http_status ${row.expect.http_status} differs from the catalogue's ${entry.http_status}`);
      if (entry.retryable !== row.expect.retryable) out.push(`matrix row ${row.id}: retryable ${row.expect.retryable} differs from the catalogue's ${entry.retryable}`);
    }
  }
  return out;
}

/** Byte-level rules for a golden: LF only, one trailing newline, no BOM. It is hashed byte for byte. */
export function validateBytes(text, name) {
  const out = [];
  if (text.includes('\r')) out.push(`${name}: has CR line endings (goldens are LF, hashed byte for byte)`);
  if (text.charCodeAt(0) === 0xfeff) out.push(`${name}: starts with a byte order mark`);
  if (!text.endsWith('\n') || text.endsWith('\n\n')) out.push(`${name}: must end with exactly one newline`);
  return out;
}

function readGolden(root, path) {
  const text = readFileSync(resolve(root, path), 'utf8');
  return { text, json: JSON.parse(text) };
}

export function loadGoldens(root = REPO_ROOT) {
  return { refusals: readGolden(root, REFUSALS_PATH).json, matrix: readGolden(root, MATRIX_PATH).json };
}

export function validateAll(docs) {
  return [...validateRefusals(docs.refusals), ...validateAgainstMatrix(docs.refusals, docs.matrix)];
}

// ---- command line ----------------------------------------------------------------------------

function main(argv) {
  const root = argv[2] ? resolve(argv[2]) : REPO_ROOT;
  const findings = [];
  let docs;
  try {
    const refusals = readGolden(root, REFUSALS_PATH);
    const matrix = readGolden(root, MATRIX_PATH);
    findings.push(...validateBytes(refusals.text, REFUSALS_PATH));
    docs = { refusals: refusals.json, matrix: matrix.json };
  } catch (error) {
    findings.push(`cannot load a golden (a missing golden is a failure, never a skip): ${error.message}`);
  }
  if (docs) findings.push(...validateAll(docs));
  if (findings.length === 0) {
    process.stdout.write(`ok - ${REFUSALS_PATH} is well formed, content-free and agrees with the entitlement matrix\n`);
    return 0;
  }
  for (const finding of findings) process.stderr.write(`not ok - ${finding}\n`);
  return 1;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv);
}
